effect.shader:
const int MAX_SAMPLES = 32;
const float TAU = 6.28318530718;

void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    if (amount == 0.0) {
        fragColor = color;
        return;
    }

    int samples = clamp(int(quality + 0.5), 4, MAX_SAMPLES);
    float radius = abs(amount);
    bool spreading = amount > 0.0;

    float extreme = color.a;
    vec3 carried = color.rgb;

    for (int i = 0; i < MAX_SAMPLES; i++) {
        if (i >= samples) break;
        float angle = float(i) / float(samples) * TAU;
        // Em pixels da COMPOSIÇÃO (`acEscalaDePixel`): a prévia reduzida fica do tamanho da exportação (0.516.0).
        vec2 uv = acScreenNorm + vec2(cos(angle), sin(angle)) * (radius * acEscalaDePixel) * acTexelSize;
        vec4 texel = texture(inputImg, clamp(uv, 0.0, 1.0));

        if (spreading) {
            if (texel.a > extreme) {
                extreme = texel.a;
                carried = texel.rgb;
            }
        } else {
            extreme = min(extreme, texel.a);
        }
    }

    float alpha = extreme;
    if (softness > 0.0) {
        alpha = smoothstep(0.5 - softness, 0.5 + softness, alpha);
    }

    // Ao aparar, a cor não muda: só some alfa. Ao espalhar, a cor vem da
    // amostra vencedora, senão a borda nova nasceria preta.
    fragColor = vec4(spreading ? carried : color.rgb, alpha);
}
